  "settings.gate": "Останавливать агентов перед правкой файла, который меняет другая сессия",
  "settings.gateHelp":
    "Тогда агент ждёт, пока ты решишь здесь. Действует для командных сессий, запущенных, пока это включено, но не внутри WSL. Это согласует твои сессии и не является защитой: изменения через терминал не задерживаются, а если Hangar не может ответить, изменение выполняется.",
  "settings.gateNeedsClaims": "Нужна опция «{setting}».",
  "gate.noEndpoint":
    "В этой сессии изменения не приостанавливаются: Hangar не смог запустить локальную точку для хуков.",
  "gate.launcher":
    "В этой сессии изменения не приостанавливаются: путь к папке данных Hangar содержит символы, которые cmd.exe стал бы интерпретировать.",
  "gate.profileSettings":
    "В этой сессии изменения не приостанавливаются: её профиль уже передаёт собственные --settings, поэтому Hangar не добавляет свои.",
  "settings.subAgentExcerpts": "Показывать текст субагентов",
  "settings.subAgentExcerptsHelp":
    "Показывает задачу, текст и вызовы инструментов каждого субагента с их командами, путями к файлам и веб-адресами, первые строки каждого результата, а в боковой панели то, над чем работает последний вызов. Hangar скрывает ключи и пароли, которые распознаёт, но не может найти все. Ничего не сохраняется. Если выключено, видны только названия инструментов и числа.",

